package com.rk.fooddelivery.payment.service; import com.rk.fooddelivery.payment.entity.PaymentRefund; import com.rk.fooddelivery.payment.repository.PaymentRefundRepository; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class RefundService { private final PaymentRefundRepository refunds; public RefundService(PaymentRefundRepository refunds){this.refunds=refunds;} @Transactional public void requestOnce(UUID orderId,String reason){if(refunds.existsByOrderIdAndReason(orderId,reason))return;refunds.save(new PaymentRefund(orderId,reason));} }
